class Task:
    def __init__(self, C_i, P_i):
        self.C = C_i  # Running time
        self.P = P_i  # Period (and implicit deadline)

def create_task_system(task_data_list):
    task_system = []
    for C, P in task_data_list:
        task_system.append(Task(C, P))
    return task_system

def schedule_job(ready_jobs, current_running_job):
    if not ready_jobs:
        return None # Processor idle

    highest_priority_job = None
    max_priority = -1 # Assuming higher number means higher priority

    for job in ready_jobs:
        if job.priority > max_priority:
            max_priority = job.priority
            highest_priority_job = job

    if current_running_job and highest_priority_job.priority > current_running_job.priority:
        # Preempt the current job
        return highest_priority_job
    elif not current_running_job:
        return highest_priority_job
    else:
        return current_running_job # Continue running current job

def is_system_feasible(task_system):
    # Sort tasks by period for Rate-monotonic priority assignment
    sorted_tasks = sorted(task_system, key=lambda t: t.P)

    for j, task_j in enumerate(sorted_tasks):
        # Higher priority tasks are those appearing before task_j in the sorted list
        higher_priority_tasks = sorted_tasks[:j]

        r_j = calculate_response_time_equation(task_j, higher_priority_tasks)
        if r_j > task_j.P:
            return False # System is not feasible if any task misses its deadline
    return True # All tasks are feasible
